import { mkdir, rm, writeFile } from 'node:fs/promises';
import { dirname, resolve, sep } from 'node:path';

/**
 * Media storage driver (docs/ARCHITECTURE.md §6, RF-MED-07). Keys are
 * generated by Cleitext (`<siteId>/<yyyy>/<mm>/<uuid>.<ext>`), never derived
 * from uploaded file names.
 */
export interface MediaStorage {
  put(key: string, data: Buffer): Promise<void>;
  delete(key: string): Promise<void>;
  /** Public URL path of a stored file. */
  url(key: string): string;
}

export class DiskStorage implements MediaStorage {
  constructor(private readonly root: string) {}

  async put(key: string, data: Buffer): Promise<void> {
    const path = this.pathOf(key);
    await mkdir(dirname(path), { recursive: true });
    await writeFile(path, data, { flag: 'wx' });
  }

  async delete(key: string): Promise<void> {
    await rm(this.pathOf(key), { force: true });
  }

  url(key: string): string {
    return `/media/${key}`;
  }

  /** Absolute path, guaranteed to stay inside the storage root. */
  pathOf(key: string): string {
    const root = resolve(this.root);
    const path = resolve(root, key);
    if (!path.startsWith(root + sep)) throw new Error(`Invalid storage key: ${key}`);
    return path;
  }
}
